def make_stabilizer_label(n_qubits, v, neighbors):
         paulis = ['I'] * n_qubits
         paulis[v] = 'X'
         for u in neighbors:
             paulis[u] = 'Z'
         # Qiskit label: qubit n-1 to 0
         return ''.join(reversed(paulis))

